"""Join checked supplier observations to every populated native reference."""
from pathlib import Path
import csv,json,re,hashlib
ROOT=Path(__file__).resolve().parents[2];S=ROOT/'designs/eye-camera-ov9281/electronics/r11'
def main():
    data=json.loads((S/'supplier-observations.json').read_text());offers=data['offers'];parts=json.loads((S/'components.json').read_text())['parts'];groups={}
    bib=(ROOT/'references.bib').read_text(encoding='utf8');existing={}
    for entry in re.split(r'(?=@\w+\{)',bib):
        k=re.match(r'@\w+\{([^,]+)',entry);u=re.search(r'\burl\s*=\s*\{([^}]+)\}',entry)
        if k and u:existing[u[1]]=k[1]
    for o in offers:
        if o['url'] in existing:o['key']=existing[o['url']];continue
        if re.search(r'@\w+\{'+re.escape(o['key'])+',',bib):continue
        bib+='\n@misc{'+o['key']+',\n author = {{'+o['supplier']+'}},\n title = {'+o['mpn']+' supplier listing},\n url = {'+o['url']+'},\n urldate = {2026-10-29},\n review = {excerpt},\n claim = {Supplier-listed availability and indicative USD pricing for the R11 purchasing review.},\n note = {Product-page or indexed stock and price fields reviewed. Indexed counts can differ between captures; this is not reserved inventory or a delivery commitment. '+o.get('note','')+'}\n}\n'
    (ROOT/'references.bib').write_text(bib,encoding='utf8');(S/'supplier-observations.json').write_text(json.dumps(data,indent=2)+'\n')
    for ref,p in parts.items():
        if not p['populated'] or p['mpn']=='PCB programming lands':continue
        g=groups.setdefault(p['mpn'],{'mpn':p['mpn'],'manufacturer':p['manufacturer'],'refs':[],'footprint':p['footprint'],'value':p['value']});g['refs'].append(ref)
    rows=[];subtotal=0;unpriced=[]
    for mpn,g in sorted(groups.items()):
        options=[o for o in offers if o['mpn']==mpn];assert options,mpn
        # LCSC base-code flash offer is explicitly provisional; keep its
        # contradictory DigiKey lifecycle observation in the same row.
        o=next((o for o in options if o.get('stock') and o.get('usd1') is not None),options[0]);q=len(g['refs']);price=o.get('usd1')
        if price is None:unpriced.append(mpn)
        else:subtotal+=q*price
        rows.append({**g,'quantity':q,'primary_observation':o,'all_observations':options,'extended_unit1_usd':None if price is None else q*price})
    assert sum(r['quantity'] for r in rows)==104
    report={'revision':'R11','checked_date':data['checked_date'],'scope':data['scope'],'purchasable_line_count':len(rows),'physical_package_count':104,'excluded_from_purchase':{'R7':'Do not populate','J103':'Bare PCB programming lands, already in board fabrication'},'known_unit1_price_subtotal_usd':subtotal,'unpriced_mpns':unpriced,'total_product_cost_usd':None,'total_cost_note':'The subtotal sums observed single-unit list prices times fitted quantity, including unavailable parts. It is not a complete BOM price or checkout quote. Sensor and obsolete capacitors, PCB/HDI fabrication, assembly, stencil, optics, supports, adhesive, yield, tax and shipping are unpriced. Quantity breaks may reduce the known subtotal.','rows':rows,'non_electronic_purchasing':[{'item':n,'quantity':q,'status':s,'usd':None} for n,q,s in [('C SLIM.flex six-layer circuit',1,'Custom quotation required; no fabrication order authorized'),('Windowed controller support',1,'0.10 mm FR4 plus 0.05 mm adhesive; process/material unqualified'),('Head ring support',1,'0.10 mm FR4 plus 0.05 mm adhesive'),('Compact optics holder',1,'Native model supplied; lightweight polymer/process unqualified'),('Close-focus lens and barrel',1,'Provisional M6 envelope; no qualified part number'),('Visible-blocking IR-pass filter',1,'Provisional diameter 5.2 mm and thickness 0.2 mm; spectral specification unqualified'),('Bonding and lens retention material',1,'Provisional; included in mass allowance')]],'release_blockers':['No qualified stocked OV09281-H64A source established. DigiKey obsolete listing is not independent manufacturer lifecycle confirmation.','P4 and several regulators, FETs, oscillator and capacitors have backorder, unavailable or conflicting stock observations.','Two selected capacitor codes are listed obsolete and the 16 pF code is not recommended for new designs. Suggested substitutions require a controlled component update and DC-bias/package verification.','Flash is listed obsolete at DigiKey but available under its base code at LCSC; exact packaging, lifecycle and traceability remain unresolved.','Custom fabrication, assembly and close-focus IR optics have no verified quote.'],'component_source_sha256':hashlib.sha256((S/'components.json').read_bytes()).hexdigest()}
    (S/'purchasing-bom.json').write_text(json.dumps(report,indent=2)+'\n')
    with (S/'purchasing-bom.csv').open('w',newline='',encoding='utf8') as f:
        w=csv.writer(f);w.writerow(['MPN','Manufacturer','Quantity','References','Footprint','Supplier','Web-listed status','Web-listed stock','USD at qty 1','USD at qty 10','Source','Citation key','Notes'])
        for r in rows:
            o=r['primary_observation'];w.writerow([r['mpn'],r['manufacturer'],r['quantity'],' '.join(r['refs']),r['footprint'],o['supplier'],o['status'],o.get('stock'),o.get('usd1'),o.get('usd10'),o['url'],o['key'],o.get('note','')])
    md=['# R11 mass and purchasing review','', 'The complete module screens at **1.34 g nominal**, excluding the external tether. The low/high scenarios are **0.92/1.93 g**, not confidence bounds or guaranteed limits. The under-one-gram target is **not met by the nominal estimate**.','', 'The material ledger uses actual native copper areas, the regional stack, coating/paste geometry, support and holder volumes, and per-package estimates. Copper is not added twice to a solid board envelope. Filled-via volume displaces polymer. The integrated flex and board connector are included. Most package masses and all unresolved optics remain assumptions. See `mass-budget.json` and `calculate_r11_mass.py` for every term.','', 'Nominal copper density uses the cited copper data; the polymer density is a generic Kapton proxy, not the actual mixed laminate. FR4 support density and the two buck-inductor typical masses use their cited sources. Thickness, solder, finish and most package intervals are engineering scenarios [@cdaCopperDensity2026; @dupontKaptonDensity2026; @civaFr4Density2026; @murataDfeMass2025; @wurthSlimFlex0302026].','', 'Nominal contributors: packages 0.572 g; copper 0.267 g; laminate and mask 0.250 g; solder and finish 0.071 g; supports and optics 0.182 g. Reducing area or unnecessary copper must preserve reference paths and power delivery. Moving the P4 to an off-module board would change the approved architecture and is not done here.','', '## Purchasing result','',f'All {len(rows)} electronic purchasing lines, representing 104 fitted packages, have supplier observations. R7 is DNP; J103 is part of the PCB. The known unit-1-price subtotal is **USD {subtotal:.2f}**, including some unavailable parts. This is **not the total camera cost**: the sensor, two obsolete capacitor codes and all custom fabrication/assembly/optics costs remain unpriced. The CSV is a review BOM, not an order-ready cart.','',data['scope'],'','| MPN | Qty | Supplier observation | USD, qty 1 | Evidence |','|---|---:|---|---:|---|']
    for r in rows:
        o=r['primary_observation'];price='Unpriced' if o.get('usd1') is None else f"{o['usd1']:.4f}";evidence='; '.join('@'+a['key'] for a in r['all_observations']);md.append(f"| {r['mpn']} | {r['quantity']} | {o['supplier']}: {o['status']} | {price} | [{evidence}] |")
    md+=['','## Required purchasing decisions','']+['- '+x for x in report['release_blockers']]+['','Supplier substitutes are research leads only. They are not silently installed into the native design. Recheck exact ordering codes, land patterns, height, rated/effective capacitance, crystal load and traceability before replacing parts.','', 'Review scope: exact-MPN supplier product pages and indexed excerpts checked on 2026-10-29, matched to all populated native references. Sources do not establish physical fit, manufacturer lifecycle or guaranteed delivery. No order, vendor contact or fabrication submission was made.']
    (S/'MASS-AND-PURCHASING.md').write_text('\n'.join(md)+'\n',encoding='utf8');print(json.dumps({'lines':len(rows),'packages':104,'known_price_subtotal':subtotal,'unpriced':unpriced},indent=2))
if __name__=='__main__':main()
